  <nav class="breadcrumb" aria-label="Ruta"><a href="<?= url('/') ?>">Inicio</a><span>/</span><a href="<?= url('/?category=' . $product['category'] . '#coleccion') ?>"><?= e(\App\Models\Product::CATEGORIES[$product['category']]) ?></a><span>/</span><span><?= e($product['name']) ?></span></nav>
  <div class="product-detail"><div class="product-gallery image-<?= e($product['category']) ?>"><img src="<?= image_url($product['image']) ?>" alt="<?= e($product['name']) ?>" width="600" height="660"><?php if ($product['illustrative']): ?><span class="illustration-note">Imagen ilustrativa</span><?php endif; ?></div><div class="product-info"><span class="eyebrow"><?= icon('pin') ?> <?= e($product['municipality']) ?>, TLAXCALA</span><h1><?= e($product['name']) ?></h1><p class="lead"><?= e($product['utility']) ?></p><div class="detail-price"><?= money(cents((string) $product['price'])) ?><span>MXN</span></div><p class="stock-indicator <?= $product['stock'] ? '' : 'out' ?>"><?= icon('box') ?> <?= $product['stock'] ? (int) $product['stock'] . ' unidades disponibles' : 'Por ahora, sin existencias' ?></p><dl class="product-facts"><div><dt>Materiales</dt><dd><?= e($product['material']) ?></dd></div><div><dt>Taller</dt><dd><?= e($product['seller_name']) ?></dd></div><div><dt>Categoría</dt><dd><?= e(\App\Models\Product::CATEGORIES[$product['category']]) ?></dd></div></dl>
    <?php $buyer = current_user() && current_user()['role'] === 'cliente'; ?>
    <?php if ($buyer && $product['stock']): ?><form method="post" action="<?= url('/carrito/agregar') ?>" class="add-cart-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int) $product['id'] ?>"><div><label for="quantity">Cantidad</label><input id="quantity" name="quantity" type="number" min="1" max="<?= min(99, (int) $product['stock']) ?>" value="1" required></div><button class="button button-primary"><?= icon('bag') ?> Agregar a mi selección</button></form>
    <?php elseif (!current_user() && $product['stock']): ?><a class="button button-primary full-width" href="<?= url('/ingresar') ?>"><?= icon('bag') ?> Inicia sesión para comprar</a><p class="purchase-note">¿Es tu primera visita? <a href="<?= url('/registro') ?>">Crea una cuenta</a> y empieza tu colección.</p>
    <?php elseif (!$product['stock']): ?><button class="button button-muted full-width" disabled>Producto agotado</button>
